 "content": "def transform(grid):
    """Color the trailing background cells after the rightmost foreground cell in each row."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        foreground = [c for c, v in enumerate(row) if v != bg]
        if foreground:
            for c in range(foreground[-1] + 1, w):
                if grid[r][c] == bg:
                    out[r][c] = 1
    return out
